INSERT INTO api_call_log (
    api_name, caller_id, caller_name, caller_type, caller_level,
    caller_dept, request_params, response_status, call_duration_ms
) VALUES (
    #{apiName}, #{callerId}, #{callerName}, #{callerType}, #{callerLevel},
    #{callerDept}, #{requestParams}, #{responseStatus}, #{callDurationMs}
)

mapper.select:
SELECT
    ${dimension} AS groupKey,
    COUNT(*) AS callCount,
    COUNT(DISTINCT caller_id) AS uniqueCallers
FROM api_call_log
WHERE gmt_create BETWEEN #{startDate} AND #{endDate}

    AND api_name = #{apiName}

GROUP BY ${dimension}
ORDER BY callCount DESC

SELECT DATE_FORMAT(gmt_create, #{dateFormat}) AS timeLabel, COUNT(*) AS callCount FROM api_call_log WHERE gmt_create BETWEEN #{startDate} AND #{endDate}
AND api_name = #{apiName}
GROUP BY DATE_FORMAT(gmt_create, #{dateFormat}) ORDER BY timeLabel ASC

SELECT
    IFNULL(${dimension}, '未知') AS groupKey,
    COUNT(*) AS callCount
FROM api_call_log
WHERE gmt_create BETWEEN #{startDate} AND #{endDate}

    AND api_name = #{apiName}

GROUP BY ${dimension}
ORDER BY callCount DESC

SELECT COUNT(*)
FROM api_call_log
WHERE gmt_create BETWEEN #{startDate} AND #{endDate}

    AND api_name = #{apiName}
